"""Fibonacci divisibility equivalence (fib_dvd_iff): for m>=3, F_m | F_n <=> m | n."""
from __future__ import annotations

def fib(n: int) -> int:
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a

def demo_fibonacci_divisibility_equivalence(max_m: int = 12, max_n: int = 60) -> None:
    failures = 0
    for m in range(3, max_m + 1):
        Fm = fib(m)
        for n in range(m, max_n + 1):
            if (fib(n) % Fm == 0) != (n % m == 0):
                failures += 1
    print("consistency over 3<=m<=%d, m<=n<=%d: %s" %
          (max_m, max_n, "ALL CONSISTENT" if failures == 0 else "%d FAILURES" % failures))
    n = 12; Fn = fib(n)
    print("F_12 =", Fn)
    print("Fib-divisor indices:", [m for m in range(3, n+1) if Fn % fib(m) == 0])
    print("index divisors      :", [m for m in range(3, n+1) if n % m == 0])

if __name__ == "__main__":
    demo_fibonacci_divisibility_equivalence()

"""Constructive divisibility pigeonhole (divisibility_pigeonhole)."""
from __future__ import annotations
from itertools import combinations
from typing import Dict, List, Optional, Tuple

def odd_part(x: int) -> int:
    while x % 2 == 0:
        x //= 2
    return x

def two_adic_val(x: int) -> int:
    v = 0
    while x % 2 == 0 and x > 0:
        x //= 2; v += 1
    return v

def find_divisibility_pair(subset: List[int]) -> Optional[Tuple[int, int]]:
    seen: Dict[int, int] = {}
    for x in subset:
        q = odd_part(x)
        if q in seen:
            y = seen[q]
            return (y, x) if two_adic_val(y) <= two_adic_val(x) else (x, y)
        seen[q] = x
    return None

def demo_divisibility_pigeonhole(n: int = 6) -> None:
    universe = list(range(1, 2 * n + 1))
    all_ok = all(find_divisibility_pair(list(s)) for s in combinations(universe, n + 1))
    print("every (n+1)-subset of [1,2n] has a divisibility pair (n=%d): %s" % (n, all_ok))
    extremal = list(range(n + 1, 2 * n + 1))
    has = any(b % a == 0 for a, b in combinations(extremal, 2))
    print("extremal n-subset", tuple(extremal), "has a pair:", has, "(=> n+1 is sharp)")

if __name__ == "__main__":
    demo_divisibility_pigeonhole()

"""Finite descent + Garden of Eden (finite_garden_of_eden_descent,
exists_garden_of_eden_iff_not_surjective)."""
from __future__ import annotations
from typing import Callable, List, Tuple

def is_garden_of_eden(F: Callable[[int], int], domain: List[int], y: int) -> bool:
    return all(F(x) != y for x in domain)

def stabilize(F: Callable[[int], int], x: int, N: int) -> Tuple[int, int]:
    cur = x
    for n in range(N + 1):
        nxt = F(cur)
        if nxt == cur:
            return (n, cur)
        cur = nxt
    raise RuntimeError("did not stabilize within N steps")

def demo_garden_of_eden_descent(N: int = 8) -> None:
    domain = list(range(N))
    F = lambda x: max(x - 1, 0)  # monotone, descending
    worst = max(stabilize(F, x, N)[0] for x in domain)
    print("worst-case steps:", worst, "<= |P| =", N, ":", worst <= N)
    image = sorted({F(x) for x in domain})
    surj = image == domain
    goe = [y for y in domain if is_garden_of_eden(F, domain, y)]
    print("surjective:", surj, " GoE states:", goe)
    print("exists GoE <=> not surjective:", (len(goe) > 0) == (not surj))

if __name__ == "__main__":
    demo_garden_of_eden_descent()

